/**
 * Deliveries — the document goods actually arrive on. T-166.
 *
 * ⭐ **The pivotal event in the whole domain.** Receiving is the only door stock enters by, and it
 * is where three things happen at once: quantity moves (T-161), cost is captured as a FIFO layer
 * (T-162), and value posts to the ledger (T-163). Until this table existed, none of those three
 * had a caller.
 *
 * ## One document, two labels — kept from v1
 *
 * A **delivery** is supplier-sourced; a **purchase** is staff-bought for cash and may have no
 * registered supplier; a **commissary** delivery is system-generated by T-173's cross-store
 * receipt. v1 keeps all three in one collection with one receive flow, differing only in required
 * proof and labelling, and that is right: they are the same physical event.
 *
 * ## ⭐ The photo gate is an anti-fraud control, not a nicety
 *
 * Every NEW delivery or purchase must carry proof before it can be created. v1 enforces it
 * server-side, and the reason is the obvious one: a cash purchase with no paper is
 * indistinguishable from no purchase at all.
 *
 * ⚠️ A **commissary** delivery is exempt, because it is system-generated from a confirmed
 * cross-store receipt — there is no paper to photograph, and the counterpart store's dispatch IS
 * the evidence.
 *
 * ## What v1 does that this deliberately does NOT port
 *
 * ⛔ **Auto-link / bulk-create-from-delivery.** v1 built it and then removed it: *"the auto-link's
 * amount-match heuristic produced false positives at scale, and the bulk-create action wasn't
 * atomic."* Do not re-introduce fuzzy matching.
 *
 * ⛔ **The direct "receive into a room" door.** Still present in v1's code and hard-blocked by
 * policy — *"all inbound stock now flows through the Deliveries → receive → allocate flow… so no
 * stale/future client can reintroduce off-delivery stock-in."* Not ported at all.
 */
import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  date,
  index,
  numeric,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  foreignKey,
} from 'drizzle-orm/pg-core';
import { items } from './items';
import { organizations } from './organizations';
import { persons } from './persons';
import { stockLocations } from './stock-locations';
import { storedFiles } from './stored-files';
import { stores } from './stores';
import { suppliers } from './suppliers';

export const DELIVERY_KINDS = ['supplier', 'purchase', 'commissary'] as const;
export type DeliveryKind = (typeof DELIVERY_KINDS)[number];

export const DELIVERY_STATUSES = ['draft', 'received', 'void'] as const;
export type DeliveryStatus = (typeof DELIVERY_STATUSES)[number];

/**
 * ⚠️ **A different, smaller enum than the wastage reasons** (T-164), and the split is deliberate.
 *
 * A shortage is a **supplier-relationship signal** — it feeds a conversation with a vendor about
 * what they failed to deliver. Wastage is a **stock-loss classification** — it feeds cost
 * reporting about what we destroyed. They share the word "loss" and nothing else, and merging them
 * would make both reports meaningless.
 *
 * ⭐ `not_received` is **auto-set** when a whole line is marked not received, and is excluded from
 * the manual picker: it is a system conclusion, not an operator's explanation.
 */
export const SHORTAGE_REASONS = [
  'not_received',
  'supplier_short',
  'damaged_in_transit',
  'damaged_on_arrival',
  'quality_reject',
  'count_correction',
  'other',
] as const;
export type ShortageReason = (typeof SHORTAGE_REASONS)[number];

export const deliveries = pgTable(
  'deliveries',
  {
    id: uuid('id').primaryKey().default(sql`uuidv7()`),
    orgId: uuid('org_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'restrict' }),
    storeId: uuid('store_id')
      .notNull()
      .references(() => stores.id, { onDelete: 'restrict' }),
    kind: text('kind', { enum: DELIVERY_KINDS }).notNull(),
    /** Required for `supplier`; a cash purchase may genuinely have no registered vendor. */
    supplierId: uuid('supplier_id').references(() => suppliers.id, { onDelete: 'restrict' }),
    /** The DR or invoice number written on the paper. Feeds the duplicate-risk warning. */
    referenceNo: text('reference_no'),
    deliveredOn: date('delivered_on').notNull(),
    status: text('status', { enum: DELIVERY_STATUSES }).notNull().default('draft'),
    /** ⭐ The photo gate. Enforced by a CHECK, not by the service — see the migration. */
    proofFileId: uuid('proof_file_id').references(() => storedFiles.id, { onDelete: 'restrict' }),
    receivedAt: timestamp('received_at', { withTimezone: true }),
    receivedBy: uuid('received_by').references(() => persons.id, { onDelete: 'restrict' }),
    voidedAt: timestamp('voided_at', { withTimezone: true }),
    voidedBy: uuid('voided_by').references(() => persons.id, { onDelete: 'restrict' }),
    voidReason: text('void_reason'),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => persons.id, { onDelete: 'restrict' }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }),
  },
  (t) => [
    /** ⭐ A supplier delivery names its supplier; a purchase need not. */
    check(
      'deliveries_supplier_required_check',
      sql`${t.kind} <> 'supplier' or ${t.supplierId} is not null`,
    ),
    /** ⚠️ The photo gate, as a constraint. A commissary delivery is exempt (system-generated). */
    check(
      'deliveries_proof_required_check',
      sql`${t.kind} = 'commissary' or ${t.proofFileId} is not null`,
    ),
    check(
      'deliveries_received_shape_check',
      sql`${t.status} <> 'received' or (${t.receivedAt} is not null and ${t.receivedBy} is not null)`,
    ),
    check(
      'deliveries_void_shape_check',
      sql`${t.status} <> 'void' or (${t.voidedAt} is not null and ${t.voidedBy} is not null and ${t.voidReason} is not null)`,
    ),
    /** Same supplier, same paper reference, twice — refused outright rather than warned about.
     *  ⚠️ Voided documents are excluded so a corrected re-entry is possible. */
    uniqueIndex('deliveries_supplier_reference_key')
      .on(t.supplierId, t.referenceNo)
      .where(sql`${t.referenceNo} is not null and ${t.status} <> 'void'`),
    index('deliveries_store_status_idx').on(t.storeId, t.status, t.deliveredOn),
    index('deliveries_org_idx').on(t.orgId),
    // T-398 S1 / DEF-491, migration 0194 - same-org twins of the single-column persons/stores FKs
    // above: RLS checks only this row's own org_id and the FK check runs as the table owner, so a
    // cross-org person/store was accepted. They reference `persons_org_id_id_unique` /
    // `stores_org_id_id_unique` (hand-added in migration 0194, see schema/persons.ts, schema/stores.ts).
    foreignKey({
      columns: [t.orgId, t.createdBy],
      foreignColumns: [persons.orgId, persons.id],
      name: 'deliveries_created_by_same_org_fk',
    }).onDelete('restrict'),
    foreignKey({
      columns: [t.orgId, t.receivedBy],
      foreignColumns: [persons.orgId, persons.id],
      name: 'deliveries_received_by_same_org_fk',
    }).onDelete('restrict'),
    foreignKey({
      columns: [t.orgId, t.storeId],
      foreignColumns: [stores.orgId, stores.id],
      name: 'deliveries_store_id_same_org_fk',
    }).onDelete('restrict'),
    foreignKey({
      columns: [t.orgId, t.voidedBy],
      foreignColumns: [persons.orgId, persons.id],
      name: 'deliveries_voided_by_same_org_fk',
    }).onDelete('restrict'),
  ],
);

export const deliveryLines = pgTable(
  'delivery_lines',
  {
    id: uuid('id').primaryKey().default(sql`uuidv7()`),
    deliveryId: uuid('delivery_id')
      .notNull()
      .references(() => deliveries.id, { onDelete: 'cascade' }),
    lineNo: text('line_no').notNull(),
    itemId: uuid('item_id')
      .notNull()
      .references(() => items.id, { onDelete: 'restrict' }),
    orderedQuantity: numeric('ordered_quantity', { precision: 14, scale: 3 }).notNull(),
    /** Null until the delivery is received. */
    receivedQuantity: numeric('received_quantity', { precision: 14, scale: 3 }),
    purchaseUnit: text('purchase_unit').notNull(),
    /** ⚠️ SNAPSHOTTED, per T-145's rule: correcting a pack size next year must not rewrite what a
     *  past delivery says arrived. */
    conversionFactor: numeric('conversion_factor', { precision: 14, scale: 6 }).notNull(),
    /** Per PURCHASE unit, as typed. The landed cost per base unit is derived (T-151). */
    unitCost: numeric('unit_cost', { precision: 14, scale: 4 }).notNull(),
    /** ⭐ NULL means "park it in Receiving" — never "guess the default room". */
    locationId: uuid('location_id').references(() => stockLocations.id, { onDelete: 'restrict' }),
    shortageReason: text('shortage_reason', { enum: SHORTAGE_REASONS }),
    /** Set by a manager to permit receiving above what was ordered. */
    overReceiptAllowed: boolean('over_receipt_allowed').notNull().default(false),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex('delivery_lines_delivery_line_key').on(t.deliveryId, t.lineNo),
    check('delivery_lines_ordered_positive_check', sql`${t.orderedQuantity} > 0`),
    check(
      'delivery_lines_received_non_negative_check',
      sql`${t.receivedQuantity} is null or ${t.receivedQuantity} >= 0`,
    ),
    check('delivery_lines_unit_cost_non_negative_check', sql`${t.unitCost} >= 0`),
    index('delivery_lines_item_idx').on(t.itemId),
    check('delivery_lines_ordered_quantity_finite_check', sql`${t.orderedQuantity} > '-Infinity'::numeric and ${t.orderedQuantity} < 'Infinity'::numeric`),
    check('delivery_lines_received_quantity_finite_check', sql`${t.receivedQuantity} > '-Infinity'::numeric and ${t.receivedQuantity} < 'Infinity'::numeric`),
    check('delivery_lines_conversion_factor_finite_check', sql`${t.conversionFactor} > '-Infinity'::numeric and ${t.conversionFactor} < 'Infinity'::numeric`),
    check('delivery_lines_unit_cost_finite_check', sql`${t.unitCost} > '-Infinity'::numeric and ${t.unitCost} < 'Infinity'::numeric`),
  ],
);
